539	  private dueCentsOf(person: PersonView): number | null {
540	    const today = this.session.sheet()?.today;
541	    const gradeToday = this.gradeToday(person);
542	    let total = 0;
543	    let keptFigure = false;
544	    for (const c of this.claimsOf(person.id)) {
545	      if (!this.countsLive(c)) continue;
546	      const grade = gradeOn(person.grades, c.date);
547	      const due = claimOwedCents(c, this.ratesOf(grade), this.floor.cents(), this.lateness(), this.claims());
548	      if (due !== null) total += due;
549	      if (keepsFigure(c)) keptFigure = true;
550	      // A live figure at a grade other than today's is not undone by today's grade having no rate.
551	      if (due !== null && grade !== gradeToday) keptFigure = true;
552	      // Nor is a live figure on a claim dated by today undone by its rate having ended since.
553	      if (due !== null && today !== undefined && c.date <= today) keptFigure = true;
