601	  /** A claim moved to another person: listed first, as their newest claim, whatever its date. */
602	  protected claimReassigned(claim: ClaimView): void {
603	    this.claims.update((list) => [claim, ...list.filter((c) => c.id !== claim.id)]);
604	  }
605	
606	  /** A quick-add's claim, and its person when the quick-add added them. */
607	  protected quickAdded(added: QuickAddView): void {
608	    if (!this.people().some((p) => p.id === added.person.id)) this.people.update((list) => [...list, added.person]);
609	    this.claimAdded(added.claim);
610	  }
611	
612	  protected selectClaim(id: number, on: boolean): void {
613	    this.selectedClaims.update((ids) => {
614	      const next = new Set(ids);
615	      if (on) next.add(id);
616	      else next.delete(id);
617	      return next;
618	    });
619	  }
620	
621	  /** Open the selected claims together, in list order; each that cannot be opened is left as it is. */
622	  protected async openSelected(): Promise<void> {
623	    const sheet = this.session.sheet();
624	    if (!sheet || this.bulkOpening()) return;
625	    this.bulkResult.set(null);
626	    this.bulkError.set('');
627	    this.bulkOpening.set(true);
628	    try {
629	      const result = await this.claimsApi.openSelected(sheet.id, [...this.selectedClaims()]);
630	      if (this.session.sheet()?.id !== sheet.id) return;
631	      for (const claim of result.claims) this.claimSaved(claim);
632	      this.selectedClaims.set(new Set());
633	      this.bulkResult.set({ opened: result.opened, refused: result.refused });
634	    } catch {
635	      if (this.session.sheet()?.id === sheet.id) this.bulkError.set('The selected claims could not be opened.');
636	    } finally {
637	      this.bulkOpening.set(false);
638	    }
639	  }
640	
641	  protected claimSaved(claim: ClaimView): void {
642	    this.claims.update((list) => list.map((c) => (c.id === claim.id ? claim : c)));
643	  }
644	
645	  private reset(): void {
646	    this.editingId.set(null);
647	    this.error.set('');
648	    this.form.reset({ name: '', grade: 'A', gradeFrom: '' }, { emitEvent: false });
649	  }
650	
651	  protected edit(person: PersonView): void {
652	    this.personError.set(null);
653	    this.patronError.set(null);
654	    this.editingId.set(person.id);
655	    this.editingVersion.set(person.version);
656	    this.error.set('');
657	    this.form.setValue({ name: person.name, grade: this.gradeToday(person), gradeFrom: '' }, { emitEvent: false });
658	  }
659	
660	  protected cancel(): void {
661	    this.reset();
662	  }
663	
664	  /** After an edit was refused because someone else saved the person meanwhile: re-read the people
665	   *  and show the person's current values in the editor, keeping the refusal showing. */
666	  private async showCurrent(sheetId: string, id: number): Promise<void> {
667	    try {
668	      const people = await this.api.list(sheetId);
669	      if (this.session.sheet()?.id !== sheetId) return;
670	      this.people.set(people);
671	      const current = people.find((p) => p.id === id);
672	      if (current && this.editingId() === id) {
673	        this.editingVersion.set(current.version);
674	        this.form.setValue({ name: current.name, grade: this.gradeToday(current), gradeFrom: '' }, { emitEvent: false });
675	      }
676	    } finally {
677	      this.error.set('Someone else has saved this person since you opened it; the form now shows their changes.');
678	    }
679	  }
680	
681	  protected async submit(): Promise<void> {
682	    // A second submit before the first has answered is ignored, so it stores one record, not two.
683	    if (this.saving()) return;
684	    const sheet = this.session.sheet();
685	    if (!sheet) return;
686	    this.error.set('');
687	    const value = this.form.getRawValue();
688	    if (!value.name.trim()) {
689	      this.error.set('Type a name for the person.');
690	      return;
691	    }
692	    if (!GRADES.includes(value.grade)) {
693	      this.error.set('Choose a grade of A, B or C.');
694	      return;
695	    }
696	    const id = this.editingId();
697	    const gradeFrom = value.gradeFrom.trim();
698	    if (id !== null && gradeFrom !== '' && !DATE.test(gradeFrom)) {
699	      this.error.set('Type the grade\'s from-date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
700	      return;
701	    }
702	    this.saving.set(true);
703	    try {
704	      if (id === null) {
705	        const added = await this.api.add(sheet.id, { name: value.name.trim(), grade: value.grade });
706	        if (this.session.sheet()?.id === sheet.id) this.people.update((list) => [...list, added]);
707	      } else {
708	        const saved = await this.api.update(sheet.id, id,
709	          { name: value.name.trim(), grade: value.grade, gradeFrom: gradeFrom === '' ? null : gradeFrom,
710	            version: this.editingVersion() });
711	        if (this.session.sheet()?.id === sheet.id) {
712	          this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
713	        }
714	      }
715	      if (this.session.sheet()?.id === sheet.id) this.reset();
716	    } catch (e) {
717	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
718	        await this.showCurrent(sheet.id, id);
719	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
720	        this.error.set('That name is already in use on the sheet.');
721	      } else {
722	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
723	      }
724	    } finally {
725	      this.saving.set(false);
726	    }
727	  }
728	}
